import javax.swing.*;import java.awt.*;
public class OtherEarningsSettingsPanel extends JPanel {private final JTextField multiplier=new JTextField(Money.text(CompanyPolicyStore.otMultiplier()),12),limit=new JTextField(Money.text(CompanyPolicyStore.maxOtLimit()),12),totalLimit=new JTextField(Money.text(CompanyPolicyStore.maxTotalLimit()),12);public OtherEarningsSettingsPanel(){setLayout(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.insets=new Insets(8,8,8,8);c.fill=GridBagConstraints.HORIZONTAL;row(c,0,"OT Rate Multiplier (e.g. 2.00 = 2x Double Pay)",multiplier);row(c,1,"Max OT limit (hours per month)",limit);row(c,2,"Max Total Extra Hours Limit",totalLimit);JButton save=new JButton("Save OT & Earnings Settings");save.addActionListener(e->save());c.gridx=1;c.gridy=3;add(save,c);}private void row(GridBagConstraints c,int row,String label,JTextField field){c.gridx=0;c.gridy=row;add(new JLabel(label),c);c.gridx=1;add(field,c);}private void save(){try{double otMultiplier=Money.round(Double.parseDouble(multiplier.getText())),maxOt=Money.round(Double.parseDouble(limit.getText())),maxTotal=Money.round(Double.parseDouble(totalLimit.getText()));if(otMultiplier<0||maxOt<0||maxTotal<maxOt)throw new NumberFormatException();CompanyPolicyStore.otMultiplier(otMultiplier);CompanyPolicyStore.maxOtLimit(maxOt);CompanyPolicyStore.maxTotalLimit(maxTotal);JOptionPane.showMessageDialog(this,"OT and other earnings settings saved.");}catch(NumberFormatException e){JOptionPane.showMessageDialog(this,"Enter valid non-negative limits; total limit must be at least the OT limit.");}}}
